#include "../boot/KernelBoot.h"
#include "guardian/Security.h"
#include "DesktopViewer.h"
#include <iostream>
int main(int argc,char** argv){using namespace av::microvm;try{state::Require(argc>=6,"Usage: guardian-desktop KERNEL VOLUME MANIFEST BINDING NEW_OUTPUT [--interactive | --script FILE] [--state FILE] [--seconds N]");const auto kernel=boot::KernelImage::Read(argv[1]);state::Require(kernel.SupportsDesktop(),"Desktop kernel required");const auto volume=state::ReadFile(argv[2],guardian::pevolume::MaxBytes);const auto binding=compatibility::Read(argv[4],argv[3]);const auto manifest=state::ReadFile(argv[3],4u<<20);const auto manifestHash=compatibility::Sha256(manifest);state::Require(std::memcmp(manifestHash.data(),binding.manifestSha,32)==0,"Manifest changed");state::Require(guardian::pevolume::Valid(volume.data(),uint32_t(volume.size())),"Volume rejected");const auto& header=*reinterpret_cast<const guardian::pevolume::Header*>(volume.data());const auto& root=header.entries[header.root];compatibility::Verify(binding,kernel.FileBytes(),std::span<const uint8_t>(volume).subspan(root.offset,root.bytes));const auto hash=compatibility::Sha256(volume);state::Require(!std::memcmp(hash.data(),binding.runtimeSha,32),"Volume binding mismatch");
    desktop_session::Options desktop;desktop.telemetryCapacity=65536;desktop.output=std::filesystem::absolute(argv[5]);std::vector<uint8_t> previous;uint32_t seconds=30;
    for(int i=6;i<argc;++i){const std::string option=argv[i];if(option=="--interactive")desktop.interactive=true;else if(option=="--script"&&i+1<argc)desktop.script=desktop_session::ReadScript(argv[++i]);else if(option=="--state"&&i+1<argc){previous=state::ReadFile(argv[++i],65536);state::Require(previous.size()==65536,"State size rejected");}else if(option=="--seconds"&&i+1<argc){seconds=uint32_t(std::stoul(argv[++i]));state::Require(seconds>=1&&seconds<=120,"Time budget rejected");}else throw std::runtime_error("Desktop option rejected");}
    std::unique_ptr<desktop_session::Viewer> viewer;if(desktop.interactive){state::Require(desktop.script.empty(),"Select interactive or scripted input");viewer=std::make_unique<desktop_session::Viewer>();desktop.poll=[&](){return viewer->Poll();};desktop.display=[&](const guardian::desktop::Frame& frame,const uint32_t* pixels){viewer->Display(frame,pixels);};}
    state::Require(!std::filesystem::exists(desktop.output),"Use a new output directory");std::filesystem::create_directories(desktop.output);state::Lease lease(desktop.output/"session.lock");state::AtomicWrite(desktop.output/"nt-manifest.json",manifest);guardian::telemetry::Policy analysisPolicy;analysisPolicy.eventLimit=guardian::telemetry::MaxEvents;boot::CpuOptions cpu;cpu.enabled=cpu.processes=cpu.graphics=true;boot::KernelBootSession session;session.Prepare(kernel,256ull<<20,1,cpu,{}, {},{},nullptr,{},nullptr,nullptr,&analysisPolicy,0,{},&binding,volume,previous,desktop);const auto result=session.Run(std::chrono::seconds(seconds));boot::WriteBootReport(desktop.output/"boot.json",{result});if(const auto* trace=session.Analysis()){state::AtomicText(desktop.output/"analysis.json",trace->Json());state::AtomicText(desktop.output/"analysis.html",trace->Html());}std::cout<<result.console;if(!result.success){std::cerr<<result.error<<'\n';return 3;}const auto* data=static_cast<const uint8_t*>(session.Machine().RamData());state::AtomicWrite(desktop.output/"security-state.bin",std::span<const uint8_t>(data+guardian::security::StateGpa,65536));std::cout<<"Desktop application executed in MiniNT CPL3\n";return 0;
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 2;}}
